const findings = [
  {id:'WG-012', severity:'Critical', title:'Untrusted pull request input reaches shell', workflow:'pull-request.yml', location:'line 42', evidence:'run: echo "${{ github.event.pull_request.title }}"', description:'A pull request title is attacker-controlled input. Interpolating it directly into a shell command can allow command injection.', remediation:'Pass the value through an environment variable and quote it, or use a GitHub Action that handles the value as data.', confidence:'High'},
  {id:'WG-004', severity:'High', title:'Workflow token has write-all permissions', workflow:'release.yml', location:'line 4', evidence:'permissions: write-all', description:'This workflow grants the built-in token broad write permissions. A compromised action or unsafe input could modify repository resources.', remediation:'Set permissions to read-all at workflow level, then grant only the specific permission needed by each job.', confidence:'High'},
  {id:'WG-021', severity:'High', title:'Third-party action is not pinned to a commit', workflow:'release.yml', location:'line 29', evidence:'uses: acme/upload-release@v3', description:'Tags can move after review. This reference could execute different code in a future workflow run.', remediation:'Pin the action to a full-length commit SHA and document the source version in a comment.', confidence:'High'},
  {id:'WG-021', severity:'Medium', title:'Third-party action is not pinned to a commit', workflow:'ci.yml', location:'line 18', evidence:'uses: actions/setup-node@v4', description:'A moving version tag makes the workflow dependent on future changes outside your review process.', remediation:'Pin the action to a full-length commit SHA and review Dependabot updates deliberately.', confidence:'High'},
  {id:'WG-008', severity:'Medium', title:'pull_request_target can access write credentials', workflow:'deploy.yml', location:'line 6', evidence:'on: pull_request_target', description:'This trigger runs in the base repository context and requires special care with untrusted pull request content.', remediation:'Use pull_request for untrusted contributions, or avoid checking out and executing pull request code in this workflow.', confidence:'Medium'},
  {id:'WG-015', severity:'Medium', title:'Job permissions not explicitly declared', workflow:'ci.yml', location:'line 12', evidence:'jobs: test:', description:'Without explicit job permissions, the effective token scope is harder to audit and may change with repository defaults.', remediation:'Declare the minimum required permissions at workflow or job level.', confidence:'Medium'}
];
let workflows = [
  {name:'release.yml', triggers:'push · workflow_dispatch', findings:2, status:'Needs review'},
  {name:'pull-request.yml', triggers:'pull_request', findings:1, status:'Needs review'},
  {name:'ci.yml', triggers:'push · pull_request', findings:2, status:'Needs review'},
  {name:'deploy.yml', triggers:'pull_request_target', findings:1, status:'Needs review'}
];
const cloneFindings = list => list.map(f=>({...f}));
const defaultReports = [
  {date:'Today, 10:18 AM', revision:'1a2c9f8', findings:6, status:'Completed', reportFindings:cloneFindings(findings)},
  {date:'Nov 12, 4:32 PM', revision:'6f912ce', findings:5, status:'Completed', reportFindings:cloneFindings(findings.slice(1))},
  {date:'Nov 08, 9:06 AM', revision:'0e3b44f', findings:5, status:'Completed', reportFindings:cloneFindings(findings.slice(0,5))}
];

let selected = 0;
let scanning = false;
let history = (JSON.parse(localStorage.getItem('wg-history') || 'null') || defaultReports).map(report=>({...report,reportFindings:report.reportFindings||cloneFindings(findings)}));
let retention = Number(localStorage.getItem('wg-retention') || 20);
let activeReportFindings = cloneFindings(history[0]?.reportFindings || findings);
let cacheEnabled = localStorage.getItem('wg-cache-enabled') !== 'false';
const $ = selector => document.querySelector(selector);
const escapeHtml = value => String(value).replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
const sevClass = severity => severity.toLowerCase();

function setTheme(theme){
  const isDark=theme==='dark'; document.documentElement.dataset.theme=theme; localStorage.setItem('wg-theme',theme);
  const button=$('#themeToggle'), settingsButton=$('#settingsTheme');
  button.textContent=isDark?'☼':'◐'; button.title=isDark?'Switch to light theme':'Switch to dark theme'; button.setAttribute('aria-label',button.title); button.setAttribute('aria-pressed',String(isDark));
  settingsButton.textContent=isDark?'Dark':'Light'; settingsButton.setAttribute('aria-pressed',String(isDark));
}
function findingRowMarkup(finding,index){return `<button type="button" class="finding-row ${index===selected?'active':''}" data-select="${index}" aria-label="View ${escapeHtml(finding.severity.toLowerCase())} finding: ${escapeHtml(finding.title)}"><i class="finding-bar ${sevClass(finding.severity)}"></i><span class="finding-main"><span class="finding-title">${escapeHtml(finding.title)}</span><span class="finding-meta">${escapeHtml(finding.id)} · ${escapeHtml(finding.workflow)} · ${escapeHtml(finding.location)}</span></span><span class="badge ${sevClass(finding.severity)}">${escapeHtml(finding.severity)}</span></button>`;}
function renderPriority(){$('#priorityList').innerHTML=activeReportFindings.slice(0,3).map((finding,index)=>findingRowMarkup(finding,index)).join('');}
function filtered(){const severity=$('#severityFilter')?.value||'all',workflow=$('#workflowFilter')?.value||'all',query=($('#findSearch')?.value||'').toLowerCase();return activeReportFindings.map((finding,index)=>({...finding,index})).filter(finding=>(severity==='all'||finding.severity===severity)&&(workflow==='all'||finding.workflow===workflow)&&(!query||`${finding.title} ${finding.id} ${finding.workflow}`.toLowerCase().includes(query)));}
function detailMarkup(finding){if(!finding)return '<p class="muted">Select a finding to inspect evidence and remediation guidance.</p>';return `<div class="detail-top"><span class="badge ${sevClass(finding.severity)}">${escapeHtml(finding.severity)}</span><span class="finding-meta">${escapeHtml(finding.id)}</span></div><h2>${escapeHtml(finding.title)}</h2><p>${escapeHtml(finding.description)}</p><div class="detail-section"><h3>Evidence</h3><div class="evidence">${escapeHtml(finding.workflow)} · ${escapeHtml(finding.location)}<br>${escapeHtml(finding.evidence)}</div></div><div class="detail-section"><h3>Recommended remediation</h3><p class="remediation">${escapeHtml(finding.remediation)}</p></div><div class="detail-section"><h3>Detection confidence</h3><p>${escapeHtml(finding.confidence)} · Rule set 2026.11</p></div>`;}
function detail(finding){$('#detailCard').innerHTML=detailMarkup(finding);}
function renderFindings(){const results=filtered();$('#findingTotal').textContent=results.length;$('#findingList').innerHTML=results.length?results.map(finding=>findingRowMarkup(finding,finding.index)).join(''):'<div class="empty"><strong>No findings match these filters.</strong><p>Try changing the severity or workflow filter.</p></div>';detail(activeReportFindings[selected]);}
function renderWorkflows(){$('#workflowList').innerHTML=workflows.map(workflow=>`<div class="workflow-row"><div class="file-icon">⌘</div><div><strong>${escapeHtml(workflow.name)}</strong><span>${escapeHtml(workflow.triggers)}</span></div><div class="workflow-status"><span class="badge ${workflow.findings>1?'high':'medium'}">${workflow.findings} finding${workflow.findings>1?'s':''}</span><span>${escapeHtml(workflow.status)}</span></div></div>`).join('');}
function renderHistory(){if(!history.length){$('#historyList').innerHTML='<div class="empty-state"><span class="empty-icon">◷</span><strong>No reports saved</strong><p>Run a scan below to create a local report for this repository.</p></div>';return;}$('#historyList').innerHTML=history.map((report,index)=>`<div class="history-row ${index===0?'current-scan':''}" ${index===0?'id="currentScanReport" tabindex="-1"':''}><div class="file-icon">◷</div><div><strong>${escapeHtml(report.date)}${index===0?' · Latest scan':''}</strong><span>Revision ${escapeHtml(report.revision)} · Rule set 2026.11</span></div><div class="workflow-status"><span class="badge ${report.findings>6?'high':'medium'}">${report.findings} findings</span><span>${escapeHtml(report.status)}</span></div><button class="text-btn" type="button" data-view-report="${index}">View report →</button></div>`).join('');}
function toast(message){const toastEl=$('#toast');toastEl.textContent=message;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2600);}

function dialogFocusable(dialog){return [...dialog.querySelectorAll('button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])')].filter(element=>element.getClientRects().length);}
function openDialog(dialog,trigger,initialSelector){dialog._returnFocus=trigger||document.activeElement;dialog.classList.add('show');dialog.setAttribute('aria-hidden','false');requestAnimationFrame(()=>{(dialog.querySelector(initialSelector)||dialogFocusable(dialog)[0])?.focus();});}
function closeDialog(dialog){if(!dialog.classList.contains('show'))return;dialog.classList.remove('show');dialog.setAttribute('aria-hidden','true');dialog._returnFocus?.focus?.();}
function trapDialogFocus(event){if(event.key!=='Tab')return;const dialog=document.querySelector('.modal-backdrop.show, .finding-sheet-backdrop.show');if(!dialog)return;const focusable=dialogFocusable(dialog);if(!focusable.length){event.preventDefault();return;}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
function openFindingSheet(finding,trigger){if(!window.matchMedia('(max-width: 600px)').matches)return;$('#findingSheetContent').innerHTML=detailMarkup(finding);openDialog($('#findingSheet'),trigger,'#findingSheetClose');}
function closeFindingSheet(){closeDialog($('#findingSheet'));}
function show(view,{writeHash=true,scroll=true}={}){if(!document.getElementById(view))view='overview';document.querySelectorAll('.view').forEach(section=>section.classList.toggle('active',section.id===view));document.querySelectorAll('.nav-link[data-view]').forEach(link=>link.classList.toggle('active',link.dataset.view===view));if(writeHash&&location.hash!==`#${view}`)location.hash=view;if(scroll)window.scrollTo({top:0,behavior:'smooth'});}
function openReport(report){activeReportFindings=cloneFindings(report?.reportFindings||findings);selected=0;$('#severityFilter').value='all';$('#workflowFilter').value='all';$('#findSearch').value='';renderFindings();}
function download(format){const report={repository:$('#repoInput').value,scanned_at:new Date().toISOString(),revision:'1a2c9f8',rule_set:'2026.11',findings:activeReportFindings};const body=format==='json'?JSON.stringify(report,null,2):`# Branchlock report\n\n**Repository:** ${report.repository}\n\n**Revision:** ${report.revision}\n\n## Findings\n\n${report.findings.map(finding=>`### [${finding.severity}] ${finding.title}\n\n- **Rule:** ${finding.id}\n- **Location:** ${finding.workflow}:${finding.location}\n- **Remediation:** ${finding.remediation}\n`).join('\n')}`;const blob=new Blob([body],{type:format==='json'?'application/json':'text/markdown'}),anchor=document.createElement('a');anchor.href=URL.createObjectURL(blob);anchor.download=`workflow-guardian-report.${format==='json'?'json':'md'}`;anchor.click();URL.revokeObjectURL(anchor.href);closeDialog($('#modal'));toast(`${format.toUpperCase()} report downloaded`);}
function setScanState(running){document.querySelectorAll('#scanBtn,#historyScan').forEach(button=>{button.disabled=running;button.innerHTML=running?'◌ Scanning':'↻ Scan';});$('#scanNotice').classList.toggle('scanning',running);if(running)$('#scanStatusText').innerHTML='<strong>Scan in progress</strong> Reading public workflow files without credentials';}
function applyReport(report){activeReportFindings=cloneFindings(report.findings||[]);workflows=report.workflows||[];selected=0;$('#repoInput').value=report.repository;history.unshift({date:new Date(report.scanned_at).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}),revision:report.revision,findings:activeReportFindings.length,status:'Completed',reportFindings:cloneFindings(activeReportFindings)});history=history.slice(0,retention);localStorage.setItem('wg-history',JSON.stringify(history));renderPriority();renderFindings();renderWorkflows();renderHistory();$('#scanStatusText').innerHTML=`<strong>Last scan completed</strong> at revision <code>${escapeHtml(report.revision.slice(0,7))}</code> · public repository, no credentials used`;}
async function github(path){const response=await fetch(`https://api.github.com${path}`,{credentials:'omit',headers:{'Accept':'application/vnd.github+json'}});const payload=await response.json();if(!response.ok)throw new Error(response.status===403||response.status===404?'Only accessible public repositories can be scanned without credentials.':payload.message||'GitHub could not complete the scan.');return payload;}
function scanText(workflow,content){const output=[];content.split(/\r?\n/).forEach((raw,index)=>{const line=raw.trim(),number=index+1;if(/^permissions:\s*write-all\s*(?:#.*)?$/.test(line))output.push({id:'WG-004',severity:'High',title:'Workflow token has write-all permissions',workflow,location:`line ${number}`,evidence:raw,description:'This workflow grants the built-in token broad write permissions.',remediation:'Set permissions to read-all, then grant only the permissions each job requires.',confidence:'High'});if(/^on:\s*pull_request_target\s*(?:#.*)?$/.test(line)||/^pull_request_target:\s*$/.test(line))output.push({id:'WG-008',severity:'Medium',title:'pull_request_target can access write credentials',workflow,location:`line ${number}`,evidence:raw,description:'This trigger runs in the base repository context and requires special care with untrusted pull request content.',remediation:'Use pull_request for untrusted contributions, or do not execute pull-request code.',confidence:'Medium'});const action=line.match(/\buses:\s*([^\s#]+)/);if(action&&!/@[0-9a-f]{40}$/i.test(action[1]))output.push({id:'WG-021',severity:'Medium',title:'Third-party action is not pinned to a commit',workflow,location:`line ${number}`,evidence:raw,description:'A movable action reference can execute code that was not reviewed with this workflow.',remediation:'Pin the action to a full-length commit SHA.',confidence:'High'});if(/^run:\s*.*\$\{\{\s*github\.event\.pull_request\.(title|body)/.test(line))output.push({id:'WG-012',severity:'Critical',title:'Untrusted pull request input reaches shell',workflow,location:`line ${number}`,evidence:raw,description:'Pull-request title or body data is attacker-controlled.',remediation:'Pass the value through an environment variable and quote it.',confidence:'High'});});return output;}
async function startScan(){if(scanning||!navigator.onLine)return;const raw=$('#repoInput').value.trim(),match=raw.match(/^(?:https:\/\/github\.com\/)?([\w.-]+)\/([\w.-]+)$/);if(!match){toast('Enter a public GitHub owner/repository or URL');return;}scanning=true;setScanState(true);try{const repository=`${match[1]}/${match[2]}`,meta=await github(`/repos/${repository}`);if(meta.private)throw new Error('Private repositories are not supported.');const tree=await github(`/repos/${repository}/git/trees/${meta.default_branch}?recursive=1`),files=tree.tree.filter(item=>item.type==='blob'&&/^\.github\/workflows\/[^/]+\.ya?ml$/i.test(item.path));if(!files.length)throw new Error('No GitHub Actions workflow files were found.');let reportFindings=[],reportWorkflows=[];for(const file of files){const blob=await github(`/repos/${repository}/git/blobs/${file.sha}`),content=atob(blob.content.replace(/\n/g,'')),name=file.path.split('/').pop(),items=scanText(name,content);reportFindings=reportFindings.concat(items);reportWorkflows.push({name,triggers:'Scanned workflow',findings:items.length,status:items.length?'Needs review':'No findings'});}applyReport({repository,revision:tree.sha,scanned_at:new Date().toISOString(),findings:reportFindings,workflows:reportWorkflows});toast(`Scan complete — ${reportFindings.length} findings detected`);}catch(error){toast(error.message||'Scan failed.');}finally{scanning=false;setScanState(false);}}

function updateCacheControl(){const button=$('#cacheToggle'),description=$('#cacheDescription');button.classList.toggle('on',cacheEnabled);button.setAttribute('aria-pressed',String(cacheEnabled));description.textContent=cacheEnabled?'Cache the application shell so saved reports remain readable offline.':'Offline shell caching is disabled. Saved reports remain in this browser.';}
async function setOfflineCache(enabled){cacheEnabled=enabled;localStorage.setItem('wg-cache-enabled',String(enabled));updateCacheControl();if(!('serviceWorker' in navigator)){toast('Offline caching is not supported in this browser.');return;}try{if(enabled){await navigator.serviceWorker.register('./sw.js');toast('Offline shell caching enabled');return;}const registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.map(registration=>registration.unregister()));if('caches' in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('branchlock-')).map(key=>caches.delete(key)));}toast('Offline shell caching disabled');}catch{toast(enabled?'Offline caching could not be enabled':'Offline cache cleanup could not be completed');}}
function updateNetworkStatus(){const online=navigator.onLine;$('#networkStatus').textContent=online?'Online':'Offline';$('#networkStatus').setAttribute('aria-label',online?'Network status: online':'Network status: offline');}
function initializeScanner(){$('#scanStatusText').innerHTML='<strong>Ready to scan</strong> public GitHub Actions workflows directly from this browser. No credentials are requested or retained.';}

document.addEventListener('click',event=>{const nav=event.target.closest('[data-view]');if(nav){event.preventDefault();show(nav.dataset.view);}const go=event.target.closest('[data-go]');if(go)show(go.dataset.go);const finding=event.target.closest('[data-select]');if(finding){if(finding.closest('#priorityList'))openReport(history[0]);selected=Number(finding.dataset.select);renderPriority();renderFindings();openFindingSheet(activeReportFindings[selected],finding);}const reportButton=event.target.closest('[data-view-report]');if(reportButton){const report=history[Number(reportButton.dataset.viewReport)];openReport(report);show('findings');toast(`Showing report from ${report.date}`);}});
$('#scanBtn').addEventListener('click',startScan);$('#historyScan').addEventListener('click',startScan);$('#scanDetails').addEventListener('click',()=>{openReport(history[0]);show('findings');toast('Showing findings from the latest scan');});
['severityFilter','workflowFilter','findSearch'].forEach(id=>$('#'+id).addEventListener(id==='findSearch'?'input':'change',renderFindings));
$('#filterClear').addEventListener('click',()=>{$('#severityFilter').value='all';$('#workflowFilter').value='all';$('#findSearch').value='';renderFindings();});
$('#retention').value=String(retention);$('#retention').addEventListener('change',event=>{retention=Number(event.target.value);history=history.slice(0,retention);localStorage.setItem('wg-retention',String(retention));localStorage.setItem('wg-history',JSON.stringify(history));renderHistory();toast(`Keeping the newest ${retention} reports per repository`);});
$('#exportBtn').addEventListener('click',event=>openDialog($('#modal'),event.currentTarget,'#jsonExport'));$('#mdExport').addEventListener('click',()=>download('md'));$('#jsonExport').addEventListener('click',()=>download('json'));$('#modalClose').addEventListener('click',()=>closeDialog($('#modal')));$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))closeDialog($('#modal'));});
$('#findingSheetClose').addEventListener('click',closeFindingSheet);$('#findingSheet').addEventListener('click',event=>{if(event.target===$('#findingSheet'))closeFindingSheet();});
function clearReports(message){history=[];localStorage.removeItem('wg-history');renderHistory();toast(message);}
$('#clearReports').addEventListener('click',()=>{if(confirm('Clear all saved reports for this repository? This cannot be undone.'))clearReports('Reports cleared locally');});$('#clearData').addEventListener('click',()=>{if(confirm('Clear all local analysis data? This cannot be undone.'))clearReports('Local analysis data cleared');});
$('#cacheToggle').addEventListener('click',()=>setOfflineCache(!cacheEnabled));$('#helpBtn').addEventListener('click',()=>toast('Tip: findings are explainable and never modify your repository.'));$('#themeToggle').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));$('#settingsTheme').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#repoInput').focus();}if(event.key==='Escape'){closeDialog($('#modal'));closeFindingSheet();}trapDialogFocus(event);});
window.addEventListener('hashchange',()=>show(location.hash.slice(1)||'overview',{writeHash:false,scroll:false}));window.addEventListener('online',updateNetworkStatus);window.addEventListener('offline',updateNetworkStatus);
setTheme(localStorage.getItem('wg-theme')||'dark');updateCacheControl();updateNetworkStatus();renderPriority();renderFindings();renderWorkflows();renderHistory();show(location.hash.slice(1)||'overview',{writeHash:false,scroll:false});initializeScanner();
if('serviceWorker' in navigator&&cacheEnabled)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
